// Bumped with every release; the Stratek Integrations tab compares it with
// the latest version on GitHub and shows "update available".
export const CONNECTOR_VERSION = '0.2.0';
export const UPSTREAM_REPO = 'https://github.com/carbonupdates/stratek-connectors';
